#!/bin/bash
# Generated by OpenAI Codex on 2026-11-01. Deny only the newly created CATS identities.
set -euo pipefail
[[ $(id -u) == 0 ]]
export DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=l
apt-get install -y --no-install-recommends acl
files=(/var/www/fishcast/TerrierLocal/.env /var/www/fishcast/terrier-worker/.env)
if [[ ! -e /var/lib/cats-control/previous-secret-acls ]]; then
  getfacl -p "${files[@]}" > /var/lib/cats-control/previous-secret-acls
  chmod 600 /var/lib/cats-control/previous-secret-acls
fi
setfacl -m u:catsdeploy:---,g:cats-upload:--- "${files[@]}"
for file in "${files[@]}"; do
  if runuser -u catsdeploy -- test -r "$file"; then echo 'Isolation check failed'; exit 1; fi
  if runuser -u cats-carter -- test -r "$file"; then echo 'Isolation check failed'; exit 1; fi
  runuser -u www-data -- test -r "$file"
done
echo 'CATS users denied; www-data still has read access.'
